import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
register('./hook.mjs', pathToFileURL('/tmp/'));
const { GBNF } = await import('/tmp/refsrc/index.ts');

const rulesOf = (state) =>
  [...state].map((rule) => {
    const entry = { type: rule.type };
    if ('value' in rule) {
      entry.value = rule.value;
    }
    return entry;
  });

const cases = JSON.parse(readFileSync('/tmp/cases.json', 'utf8'));
const results = [];
for (const testCase of cases) {
  const record = { steps: [] };
  try {
    let state = GBNF(testCase.grammar);
    record.steps.push(rulesOf(state));
    for (const char of testCase.input) {
      state = state.add(char);
      record.steps.push(rulesOf(state));
    }
  } catch (e) {
    record.error = { name: e.name === 'Error' ? 'ValueError' : e.name, message: e.message };
  }
  results.push(record);
}
writeFileSync('/tmp/out_ts.json', JSON.stringify(results));

