from __future__ import annotations

from ..utils.errors import GrammarParseError
from .char_at import char_at

ESCAPE_CHARS = {
    "t": 9,
    "r": 13,
    "n": 10,
}

HEX_DIGITS = "0123456789abcdefABCDEF"


def parse_hex(src: str, pos: int, raw: str) -> int:
    # Mirrors `parseInt(raw, 16)`, which stops at the first non-hex character.
    digits = ""
    for char in raw:
        if char not in HEX_DIGITS:
            break
        digits += char
    if not digits:
        raise GrammarParseError(src, pos, f"Unknown escape at {src[pos]}")
    return int(digits, 16)


def parse_char(src: str, pos: int) -> tuple[int, int]:
    if pos >= len(src):
        raise GrammarParseError(
            src,
            pos,
            "Unexpected end of grammar input, failed to complete parse",
        )

    if src[pos] == "\\":
        next_char = char_at(src, pos + 1)
        if next_char == "x":
            return (parse_hex(src, pos, src[pos + 2 : pos + 4]), 4)
        if next_char == "u":
            return (parse_hex(src, pos, src[pos + 2 : pos + 6]), 6)
        if next_char == "U":
            return (parse_hex(src, pos, src[pos + 2 : pos + 10]), 10)
        if next_char in ESCAPE_CHARS:
            return (ESCAPE_CHARS[next_char], 2)
        if next_char in ('"', "[", "]", "\\"):
            return (ord(next_char), 2)
        raise GrammarParseError(src, pos, f"Unknown escape at {src[pos]}")

    return (ord(src[pos]), 1)

